arguments.command:
cd /home/runner/work/wt/chandler && for b in rachel monica phoebe joey chandler ross; do git log origin/friend/$b --reverse --format='COMMIT %H%nDATE %ci%n%B---END---' | awk -v br="$b" '
/^COMMIT /{sha=$2}
/^DATE /{date=$2" "$3}
/^Episode: S07\/E17/{ep=1}
/^Reply-To: /{rt=$2}
/^Friend-Message: 1/{fm=1}
/^$/ && fm && ep {
  print br, sha, date, "RT="rt; fm=0; ep=0; rt="none"
}
'; done | sort -k3,4
